MessageOperations_createMessage.usage:
request := pachca.MessageCreateRequest{
	Message: pachca.MessageCreateRequestMessage{
		EntityID: int32(334),
		Content: pachca.Ptr("Отчёт готов"),
		Buttons: [][]pachca.Button{[]pachca.Button{pachca.Button{DataButton: &pachca.DataButton{
			Text: "Принять",
			Data: "accept",
		}}}},
	},
}
response, err := client.Messages.CreateMessage(ctx, request)

